const input = $json || {};

const sampleEvents = [
  {
    source: 'InterNations',
    title: 'Dubai International Social Mixer',
    start: '2026-08-07T19:30:00+04:00',
    end: '2026-08-07T22:30:00+04:00',
    location: 'Dubai Marina',
    sourceUrl: 'https://example.com/internations-event',
    estimatedCost: 120,
    currency: 'AED',
    category: 'social',
    description: 'International crowd, social mixer, solo-friendly.'
  },
  {
    source: 'Meetup',
    title: 'Dubai Expats Rooftop Social',
    start: '2026-08-08T20:00:00+04:00',
    end: '2026-08-08T23:00:00+04:00',
    location: 'Palm Jumeirah',
    sourceUrl: 'https://example.com/meetup-event',
    estimatedCost: 80,
    currency: 'AED',
    category: 'social',
    description: 'Expats social event with rooftop setting.'
  },
  {
    source: 'TimeOut Dubai',
    title: 'Rooftop Social Night',
    start: '2026-08-08T20:00:00+04:00',
    end: '2026-08-08T23:00:00+04:00',
    location: 'Palm Jumeirah',
    sourceUrl: 'https://example.com/timeout-event',
    estimatedCost: 100,
    currency: 'AED',
    category: 'nightlife',
    description: 'Rooftop social event.'
  },
  {
    source: 'Privilee',
    title: 'Beach Club Social Afternoon',
    start: '2026-08-09T15:00:00+04:00',
    end: '2026-08-09T19:00:00+04:00',
    location: 'Palm Jumeirah',
    sourceUrl: 'https://example.com/privilee-event',
    estimatedCost: 0,
    currency: 'AED',
    category: 'social',
    description: 'Member access, beach club, relaxed social environment.'
  }
];

let sourceEvents = [];

if (Array.isArray(input.events)) {
  sourceEvents = input.events;
} else if (Array.isArray(input.sourceEvents)) {
  sourceEvents = input.sourceEvents;
} else if (Array.isArray(input.connectorOutputs)) {
  sourceEvents = input.connectorOutputs.flatMap(connector => {
    if (Array.isArray(connector?.events)) return connector.events;
    if (Array.isArray(connector?.result?.events)) return connector.result.events;
    return [];
  });
} else if (Array.isArray(input.forwardedItems)) {
  sourceEvents = input.forwardedItems;
} else {
  sourceEvents = sampleEvents;
}

return [{
  json: {
    request: input.request || {
      text: 'Bu hafta sonu sosyal etkinlik bul',
      channel: 'manual_test',
      userId: 'savas'
    },
    context: input.context || {
      timezone: 'Asia/Dubai',
      userContext: {
        identity: { name: 'Savaş', language: 'Turkish' },
        locations: {
          home: 'Palm Jumeirah, Dubai',
          work: 'Abu Dhabi'
        },
        goals: {
          social: 'Build a quality international social circle',
          dating: 'Create genuine dating opportunities'
        },
        preferences: {
          venues: 'Bars, rooftops, lounges, beach clubs, social activities',
          memberships: 'Privilee, InterNations, Meetup'
        }
      },
      derivedContext: {
        calendarLoad: 'low',
        isWeekend: true,
        needsMoreSocial: true,
        preferredPlanningWindow: {
          start: '17:00',
          end: '23:00'
        }
      },
      userState: {
        energyLevel: 'high',
        mood: 'social',
        budgetAED: 300,
        maxTravelMinutes: 40
      }
    },
    sourceEvents,
    metadata: input.metadata || {
      correlationId: `social-discovery-${Date.now()}`,
      testMode: true
    }
  }
}];

const input = $json || {};
const events = Array.isArray(input.sourceEvents)
  ? input.sourceEvents
  : [];

const context = input.context || {};
const derived =
  context.derivedContext ||
  context.derived ||
  {};
const userState = context.userState || {};
const metadata = input.metadata || {};

const sourcePriority = {
  'InterNations': 10,
  'Meetup': 9,
  'Eventbrite': 8,
  'Dubai Calendar': 8,
  'Privilee': 8,
  'TimeOut Dubai': 7,
  'Google Events': 6,
  'WhatsApp Forward': 6,
  'Telegram Forward': 6,
  'Instagram Link': 6,
  'Unknown': 4
};

const normalizeText = value =>
  String(value || '')
    .trim()
    .toLocaleLowerCase('tr-TR');

const classifyCategory = event => {
  const text = normalizeText(
    `${event.category || ''} ${event.title || ''} ${event.description || ''}`
  );

  if (
    text.includes('night') ||
    text.includes('dj') ||
    text.includes('party') ||
    text.includes('rooftop') ||
    text.includes('club')
  ) return 'nightlife';

  if (
    text.includes('singles') ||
    text.includes('speed dating') ||
    text.includes('dating')
  ) return 'dating';

  if (
    text.includes('network') ||
    text.includes('mixer') ||
    text.includes('social') ||
    text.includes('expat') ||
    text.includes('community')
  ) return 'social';

  return event.category || 'social';
};

const clamp10 = value =>
  Math.max(0, Math.min(10, Number(value ?? 0)));

const eventStart = value => {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
};

const preferredStartMinutes = (() => {
  const start = derived.preferredPlanningWindow?.start || '18:00';
  const [hour, minute] = start.split(':').map(Number);
  return hour * 60 + minute;
})();

const recommendations = [];
const rejected = [];
const logs = [];

for (let index = 0; index < events.length; index++) {
  const event = events[index] || {};

  const title = String(
    event.title ||
    event.name ||
    event.eventTitle ||
    ''
  ).trim();

  if (!title) {
    rejected.push({
      index,
      reason: 'missing_title',
      event
    });
    continue;
  }

  const start =
    event.start ||
    event.startTime ||
    event.dateTime ||
    event.date ||
    null;

  const end =
    event.end ||
    event.endTime ||
    null;

  const source =
    String(event.source || event.platform || 'Unknown').trim();

  const location =
    String(
      event.location ||
      event.venue ||
      event.city ||
      ''
    ).trim();

  const sourceUrl =
    event.sourceUrl ||
    event.url ||
    event.link ||
    null;

  const description =
    String(event.description || event.text || '').trim();

  const category = classifyCategory(event);

  const startDate = start ? eventStart(start) : null;

  if (!startDate) {
    rejected.push({
      index,
      title,
      reason: 'missing_or_invalid_start',
      event
    });
    continue;
  }

  const locationText = normalizeText(location);

  const inPreferredRegion =
    locationText.includes('dubai') ||
    locationText.includes('palm') ||
    locationText.includes('marina') ||
    locationText.includes('jbr') ||
    locationText.includes('difc') ||
    locationText.includes('downtown') ||
    locationText.includes('abu dhabi');

  if (!inPreferredRegion && location) {
    rejected.push({
      index,
      title,
      reason: 'outside_preferred_region',
      location
    });
    continue;
  }

  const dubaiTime = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Dubai',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  }).format(startDate);

  const [hour, minute] = dubaiTime.split(':').map(Number);
  const startMinutes = hour * 60 + minute;

  const sourceBonus =
    sourcePriority[source] ??
    sourcePriority.Unknown;

  const socialQuality =
    category === 'social' ? 9 :
    category === 'dating' ? 9 :
    category === 'nightlife' ? 8 :
    6;

  const audienceFit =
    source === 'InterNations' ? 10 :
    source === 'Meetup' ? 9 :
    source === 'Privilee' ? 8 :
    source === 'Eventbrite' ? 8 :
    source === 'Dubai Calendar' ? 8 :
    7;

  const organicConnectionPotential =
    category === 'dating' ? 10 :
    category === 'social' ? 9 :
    category === 'nightlife' ? 8 :
    6;

  const soloFriendly =
    source === 'InterNations' || source === 'Meetup'
      ? 9
      : category === 'social'
        ? 8
        : category === 'nightlife'
          ? 7
          : 6;

  const travelConvenience =
    locationText.includes('palm') ? 10 :
    locationText.includes('marina') ||
    locationText.includes('jbr') ? 9 :
    locationText.includes('difc') ||
    locationText.includes('downtown') ? 7 :
    locationText.includes('abu dhabi') ? 4 :
    6;

  const calendarCompatibility =
    startMinutes >= preferredStartMinutes ? 9 : 6;

  const budgetAED = Number(userState.budgetAED);
  const cost = Number(
    event.estimatedCost ??
    event.cost ??
    event.price ??
    0
  );

  const valueForMoney =
    Number.isFinite(budgetAED) && Number.isFinite(cost)
      ? cost <= budgetAED
        ? 8
        : 4
      : 7;

  const funNovelty =
    category === 'nightlife' ? 9 :
    category === 'dating' ? 8 :
    category === 'social' ? 8 :
    7;

  const networkingValue =
    source === 'InterNations' ? 10 :
    source === 'Meetup' ? 8 :
    category === 'social' ? 8 :
    5;

  const confidence =
    sourceUrl ? 0.90 :
    description ? 0.75 :
    0.60;

  const priorityAdjustment =
    sourceBonus +
    (derived.needsMoreSocial === true ? 2 : 0) +
    (
      String(userState.mood || '').toLowerCase() === 'social'
        ? 1
        : 0
    );

  recommendations.push({
    id:
      event.id ||
      `${source.replace(/\s+/g, '-').toLowerCase()}-${Date.now()}-${index + 1}`,
    title,
    category,
    source,
    sourcePriority: sourceBonus,
    sourceUrl,
    start: startDate.toISOString(),
    end: end ? new Date(end).toISOString() : null,
    location,
    estimatedCost:
      Number.isFinite(cost) ? cost : null,
    currency:
      event.currency || 'AED',
    confidence,
    reason:
      description ||
      `${source} source with strong ${category} potential.`,
    rawScores: {
      calendarCompatibility: clamp10(calendarCompatibility),
      travelConvenience: clamp10(travelConvenience),
      socialQuality: clamp10(socialQuality),
      audienceFit: clamp10(audienceFit),
      fitnessValue: 1,
      growthValue: category === 'social' || category === 'dating' ? 8 : 6,
      networkingValue: clamp10(networkingValue),
      organicConnectionPotential: clamp10(organicConnectionPotential),
      funNovelty: clamp10(funNovelty),
      valueForMoney: clamp10(valueForMoney),
      soloFriendly: clamp10(soloFriendly),
      sourcePriority: clamp10(sourceBonus),
      priorityAdjustment
    },
    metadata: {
      originalSourceEvent: event,
      discoveredAt: new Date().toISOString()
    }
  });
}

const dedupeKey = event =>
  [
    normalizeText(event.title),
    normalizeText(event.location),
    String(event.start).slice(0, 16)
  ].join('|');

const map = new Map();

for (const event of recommendations) {
  const key = dedupeKey(event);
  const existing = map.get(key);

  if (!existing) {
    map.set(key, event);
    continue;
  }

  const existingPriority =
    existing.sourcePriority +
    existing.confidence * 10;

  const newPriority =
    event.sourcePriority +
    event.confidence * 10;

  if (newPriority > existingPriority) {
    map.set(key, event);
    logs.push({
      level: 'info',
      message: 'Duplicate event replaced by higher-priority source.',
      details: {
        title: event.title,
        retainedSource: event.source,
        removedSource: existing.source
      }
    });
  } else {
    logs.push({
      level: 'info',
      message: 'Duplicate event removed.',
      details: {
        title: event.title,
        retainedSource: existing.source,
        removedSource: event.source
      }
    });
  }
}

const uniqueRecommendations = [...map.values()]
  .sort((a, b) => {
    if (b.sourcePriority !== a.sourcePriority) {
      return b.sourcePriority - a.sourcePriority;
    }

    return b.confidence - a.confidence;
  });

const topRecommendations =
  uniqueRecommendations.slice(0, 20);

return [{
  json: {
    success: true,
    result: {
      agent: 'social_discovery',
      summary:
        `Found ${topRecommendations.length} unique social opportunities from ${events.length} source items.`,
      sourcePriority,
      recommendations: topRecommendations,
      rejectedEvents: rejected
    },
    memoryUpdates: topRecommendations.map(item => ({
      type: 'discovered_event',
      operation: 'append',
      payload: {
        id: item.id,
        title: item.title,
        source: item.source,
        start: item.start,
        location: item.location,
        status: 'discovered',
        discoveredAt: item.metadata.discoveredAt
      }
    })),
    approvalRequests: [],
    logs: [
      {
        timestamp: new Date().toISOString(),
        workflow: 'Concierge OS - Social Discovery Agent',
        level: rejected.length ? 'warning' : 'info',
        correlationId: metadata.correlationId || '',
        message:
          `Normalized ${topRecommendations.length} social recommendations.`,
        details: {
          sourceItemCount: events.length,
          recommendationCount: topRecommendations.length,
          rejectedCount: rejected.length,
          duplicateLogCount: logs.length
        }
      },
      ...logs.map(log => ({
        timestamp: new Date().toISOString(),
        workflow: 'Concierge OS - Social Discovery Agent',
        correlationId: metadata.correlationId || '',
        ...log
      }))
    ],
    nextAction: {
      type: 'rank_recommendations',
      targetWorkflow: 'Concierge OS - Recommendation Engine'
    },
    error: null
  }
}];
